module popcount16 (
    input  logic [15:0] x,
    output logic [4:0]  count
);

logic [4:0] count0;
logic [4:0] count1;

assign count0 = x[0]  ? 1 : 0;
assign count0 = count0 + (x[1] ? 1 : 0);
assign count0 = count0 + (x[2] ? 1 : 0);
assign count0 = count0 + (x[3] ? 1 : 0);
assign count0 = count0 + (x[4] ? 1 : 0);

assign count1 = (x[0]  | x[1]) ? 1 : 0;
assign count1 = count1 + ((x[2]  | x[3]) ? 1 : 0);
assign count1 = count1 + ((x[4]  | x[5]) ? 1 : 0);
assign count1 = count1 + ((x[6]  | x[7]) ? 1 : 0);
assign count1 = count1 + ((x[8]  | x[9]) ? 1 : 0);
assign count1 = count1 + ((x[10] | x[11]) ? 1 : 0);
assign count1 = count1 + ((x[12] | x[13]) ? 1 : 0);
assign count1 = count1 + ((x[14] | x[15]) ? 1 : 0);

assign count = count0 + count1;

endmodule

module rtl_checker (
    input logic [15:0] x,
    input logic [4:0] count
);
    // The numerical output is 0 through 16. This circuit is combinational and has no clock or reset.
    // Inputs are unrestricted. The formal profile checks every input combination with these exact widths.
    always_comb begin
        // Check if count is equal to the number of set bits in x.
        assert(count == $countones(x));
    end
endmodule
